// GinServerOptions provides options for the Gin server.
type GinServerOptions struct {
	BaseURL      string
	Middlewares  []MiddlewareFunc
	ErrorHandler func(*gin.Context, error, int)
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.GET(options.BaseURL+"/integrations/catalog", wrapper.ListCatalog)
	router.GET(options.BaseURL+"/integrations/connections", wrapper.ListConnections)
	router.DELETE(options.BaseURL+"/integrations/ai", wrapper.DisconnectAIProvider)
	router.GET(options.BaseURL+"/integrations/ai", wrapper.GetAIConnection)
	router.POST(options.BaseURL+"/integrations/ai", wrapper.ConnectAIProvider)
	router.GET(options.BaseURL+"/integrations/sales-channels", wrapper.ListSalesChannels)
	router.POST(options.BaseURL+"/integrations/sales-channels", wrapper.CreateSalesChannel)
	router.DELETE(options.BaseURL+"/integrations/sales-channels/:id", wrapper.DeleteSalesChannel)
	router.PATCH(options.BaseURL+"/integrations/sales-channels/:id", wrapper.UpdateSalesChannel)
	router.GET(options.BaseURL+"/integrations/sales-channels/:id/products", wrapper.ListSalesChannelProducts)
	router.PUT(options.BaseURL+"/integrations/sales-channels/:id/products/:productId/override", wrapper.SetSalesChannelProductOverride)
	router.DELETE(options.BaseURL+"/integrations/connections/:id", wrapper.DeleteConnection)
	router.PATCH(options.BaseURL+"/integrations/connections/:id/settings", wrapper.UpdateConnectionSettings)
	router.POST(options.BaseURL+"/integrations/connections/:id/webhook-secret", wrapper.SetWebhookSecret)
	router.GET(options.BaseURL+"/integrations/webhook-fallback-events", wrapper.ListWebhookFallbackEvents)
	router.POST(options.BaseURL+"/integrations/webhook-fallback-events/:id/retry", wrapper.RetryWebhookFallbackEvent)
	router.DELETE(options.BaseURL+"/integrations/webhook-fallback-events/:id", wrapper.AbandonWebhookFallbackEvent)
	router.GET(options.BaseURL+"/integrations/connections/:id/woo-taxes", wrapper.ListWooTaxes)
	router.GET(options.BaseURL+"/integrations/connections/:id/woo-categories", wrapper.ListWooCategories)
	router.GET(options.BaseURL+"/integrations/connections/:id/category-links", wrapper.ListExternalCategoryLinks)
	router.POST(options.BaseURL+"/integrations/connections/:id/category-links", wrapper.UpsertExternalCategoryLink)
	router.DELETE(options.BaseURL+"/integrations/connections/:id/category-links/:linkId", wrapper.DeleteExternalCategoryLink)
	router.POST(options.BaseURL+"/integrations/connections/:id/test", wrapper.TestConnection)
	router.DELETE(options.BaseURL+"/integrations/connections/:id/imported-products", wrapper.DeleteAllImportedProducts)
	router.POST(options.BaseURL+"/integrations/connections/:id/import", wrapper.ImportWooProducts)
	router.POST(options.BaseURL+"/integrations/connections/:id/push-product", wrapper.PushProductToWoo)
	router.POST(options.BaseURL+"/integrations/connections/:id/fetch-order", wrapper.FetchWooOrder)
	router.GET(options.BaseURL+"/integrations/connections/:id/listings/:productId", wrapper.GetProductChannelListing)
	router.GET(options.BaseURL+"/integrations/sync-logs", wrapper.ListAllSyncLogs)
	router.GET(options.BaseURL+"/integrations/sync-logs/needing-attention", wrapper.ListSyncLogsNeedingAttention)
	router.POST(options.BaseURL+"/integrations/sync-logs/:id/retry", wrapper.RetryFailedSync)
	router.POST(options.BaseURL+"/integrations/sync-logs/:id/dismiss", wrapper.DismissFailedSync)
	router.POST(options.BaseURL+"/integrations/products/:productId/resync", wrapper.ResyncProductToChannels)
	router.GET(options.BaseURL+"/integrations/connections/:id/listings/:productId/sync-logs", wrapper.ListSyncLogs)
	router.GET(options.BaseURL+"/integrations/connections/:id/sync-schedules", wrapper.ListSyncSchedules)
	router.PUT(options.BaseURL+"/integrations/connections/:id/sync-schedules", wrapper.UpsertSyncSchedules)
	router.POST(options.BaseURL+"/integrations/woocommerce/connect/start", wrapper.StartWooConnect)
	router.POST(options.BaseURL+"/integrations/woocommerce/connect/manual", wrapper.ManualConnectWooCommerce)
	router.POST(options.BaseURL+"/integrations/bol/connect", wrapper.ConnectBol)
	router.POST(options.BaseURL+"/integrations/connections/:id/push-product-bol", wrapper.PushProductToBol)
	router.GET(options.BaseURL+"/integrations/connections/:id/bol-overrides/:productId", wrapper.GetBolProductOverride)
	router.PUT(options.BaseURL+"/integrations/connections/:id/bol-overrides/:productId", wrapper.UpsertBolProductOverride)
	router.GET(options.BaseURL+"/integrations/connections/:id/bol-commission/:productId/:skuId", wrapper.GetBolCommission)
}

